:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #173c38;
  background: #d8e8db;
  font-synthesis: none;
}

* { box-sizing: border-box; }

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #d8e8db;
  background-image: radial-gradient(#b8d2bf 1.5px, transparent 1.5px);
  background-size: 18px 18px;
}

.meter {
  width: min(100%, 420px);
  padding: 30px;
  border: 3px solid #173c38;
  border-radius: 16px;
  background: #fffdf5;
  box-shadow: 8px 8px 0 #173c38;
  text-align: center;
}

.meter__header { margin-bottom: 24px; }
.taxi-icon { font-size: 40px; line-height: 1.1; }
.eyebrow, .fare-label {
  margin: 12px 0 4px;
  color: #52736b;
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.13em;
}

h1 { margin: 0; font-size: clamp(2rem, 8vw, 2.5rem); line-height: 1.1; letter-spacing: -0.04em; }
.subtitle { margin: 8px 0 0; color: #52736b; }

.fare-panel {
  padding: 20px 16px 17px;
  border: 2px solid #173c38;
  border-radius: 10px;
  background: #f4c84a;
  box-shadow: inset 0 -4px 0 rgb(23 60 56 / 10%);
}
.fare-label { margin: 0; color: #173c38; }
.fare { margin: 3px 0 0; font-size: clamp(3rem, 14vw, 4rem); font-weight: 850; line-height: 1; letter-spacing: -0.06em; font-variant-numeric: tabular-nums; }
.fare > span:first-child { margin-right: 3px; font-size: 0.55em; vertical-align: 0.2em; }
.base-note { margin: 9px 0 0; color: #385d50; font-size: 0.9rem; }

.trip-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 18px 0; }
.stat {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto auto;
  gap: 1px 9px;
  align-items: center;
  padding: 13px;
  border: 2px solid #d8e8db;
  border-radius: 9px;
  text-align: left;
}
.stat__icon { grid-row: 1 / 3; color: #3c806a; font-size: 1.5rem; font-weight: 800; }
.stat__label { color: #52736b; font-size: 0.85rem; }
.stat strong { font-size: 1.3rem; font-variant-numeric: tabular-nums; }
.stat small { color: #52736b; font-size: 0.85rem; font-weight: 600; }

.controls { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
button { font: inherit; cursor: pointer; }
.action {
  min-height: 106px;
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 3px;
  padding: 10px 6px;
  border: 2px solid #173c38;
  border-radius: 10px;
  background: #3c806a;
  color: #fffdf5;
  font-weight: 750;
  transition: transform 100ms ease, background-color 100ms ease, box-shadow 100ms ease;
}
.action__plus { font-size: 1.35rem; line-height: 1; }
.action small { color: #e7f2df; font-size: 0.85rem; font-weight: 600; }
.action:hover { background: #2f6c59; }
.action:active { transform: translateY(3px); box-shadow: inset 0 3px 0 rgb(0 0 0 / 16%); }
button:focus-visible { outline: 3px solid #b45e3b; outline-offset: 4px; }

.reset {
  margin-top: 18px;
  padding: 9px 15px;
  border: 2px solid #173c38;
  border-radius: 7px;
  background: transparent;
  color: #173c38;
  font-weight: 750;
  transition: background-color 100ms ease, transform 100ms ease;
}
.reset:hover { background: #e8f0e5; }
.reset:active { transform: translateY(2px); }
.rate-note { margin: 13px 0 0; color: #52736b; font-size: 0.85rem; }
.rate-note span { padding: 0 5px; color: #b45e3b; }

@media (max-width: 380px) {
  .meter { padding: 24px 18px; }
  .stat { padding: 11px 8px; gap: 1px 6px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: 0.01ms !important; }
}

const distanceOutput = document.getElementById('distance');
const waitingOutput = document.getElementById('waiting');
const fareOutput = document.getElementById('fare');

let distanceKm = 0;
let waitingMinutes = 0;

function render() {
  distanceOutput.textContent = distanceKm;
  waitingOutput.textContent = waitingMinutes;
  const fare = 3 + distanceKm * 1.5 + waitingMinutes * 0.4;
  fareOutput.textContent = fare.toFixed(2);
}

document.getElementById('add-km').addEventListener('click', () => {
  distanceKm += 1;
  render();
});

document.getElementById('add-minute').addEventListener('click', () => {
  waitingMinutes += 1;
  render();
});

document.getElementById('new-trip').addEventListener('click', () => {
  distanceKm = 0;
  waitingMinutes = 0;
  render();
});
